head.script:
// https://inswave01.atlassian.net/browse/WAEA-1167
// https://inswave01.atlassian.net/browse/WAEA-1168



// 테스트 설명, 유효성 값 설정
//  ★ _2 : Excel 파일 선택 팝업창 옵션(useModalDisable, features, frameModal). description 은 분리 샘플 공통.
//    · wframe 은 useModalDisable / features 의 전제 조건 설정용 컨트롤이며 본 샘플의 검증 대상이 아니다.
scwin.tData = {
    "description" : "[gridView > M > advancedExcelUpload]<br/>Excel 파일을 업로드하여 GridView 의 데이터로 설정합니다.",
    "validation" : [
        "useModalDisable(선택) 파라미터로 Excel 파일 선택 팝업창이 표시될때 부모창의 비활성화 여부를 설정합니다.",
        "useModalDisable(선택) 파라미터를 'true' 로 설정 시 부모창을 비활성화 처리합니다.",
        "useModalDisable(선택) 파라미터를 'false' 로 설정 시 부모창을 비활성화 처리하지 않습니다.",
        "useModalDisable(선택) 파라미터를 생략하면 기본값 'false' 로 동작합니다.",
        "wframe 파라미터가 true 이면 useModalDisable 파라미터는 'true' 로 동작됩니다.",
        "features(선택) 파라미터로 Excel 파일 선택 팝업창의 위치 및 크기를 설정합니다.",
        "features(선택) 파라미터로 팝업창의 left, top, width, height 속성을 설정할 수 있습니다. (ex> 'width=455,height=845')",
        "features(선택) 파라미터는 wframe 파라미터값이 true 인 경우 적용되지 않습니다.",
        "features(선택) 파라미터를 생략하면 팝업창의 위치 및 크기가 엔진 기본값으로 적용됩니다.",
        "frameModal(선택) 파라미터로 Excel 파일 선택 팝업창이 표시될때 비활성화 처리할 Frame 을 설정합니다.",
        "frameModal(선택) 파라미터를 true 로 설정 시 GridView 가 속한 Scope 의 Frame 을 비활성화 처리합니다.",
        "frameModal(선택) 파라미터를 'frame' 으로 설정 시 GridView 가 속한 Scope 의 Frame 을 비활성화 처리합니다.",
        "frameModal(선택) 파라미터를 특정 Frame ID 로 설정 시 ID 에 해당하는 Frame 을 비활성화 처리합니다.",
        "frameModal(선택) 파라미터를 설정하면 useModalDisable 파라미터는 무시됩니다.",
        "frameModal(선택) 파라미터는 String 이 아닌 Boolean 형으로 true 를 설정하여야 적용됩니다.",
        "frameModal(선택) 파라미터를 생략하면 기본값 false 로 동작합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 : 안내 라벨을 테스트 샘플 Frame 안에 생성한다.
//  · advancedExcelUpload 는 GridView 에 DataList 가 바인딩되어 있어야 동작한다.
//  · frameModal 은 GridView 가 속한 Scope(scope_id) 의 Frame 을 비활성화하므로, GridView 를 최상위 페이지 Scope 가 아닌
//    테스트 샘플 WFrame(wf_body_sample / src : /sample/common_link/gridView_M_advancedExcelUpload_2_frame.xml) 안에
//    DataList(dlt_bind) 와 함께 정적으로 선언해 두었다. (Target 재생성 시 초기 데이터 4행 복원도 해당 Frame 이 수행한다)
scwin.comp_init = async function () {
    // 안내 라벨 (테스트 샘플 Frame 의 라벨 영역에 생성)
    $c.gcm.createLabel('label="[전제]\n- name1~name4 4개 Column 그리드에 DataList 가 바인딩되어 있고 초기 데이터 4행(col1_1 ~ col4_4)이 설정되어 있음\n- GridView 는 테스트 샘플 영역 WFrame(wf_body_sample) 안에 선언되어 있음 (frameModal 의 true 또는 frame 이 가리키는 GridView Scope 의 Frame)\n- frameModal 의 특정 Frame ID 케이스는 GridView Scope 가 아닌 상단 영역 WFrame(wf_body_top) 을 대상으로 함\n- 테스트용 Excel : TSQA/src/sample/gridView/data/upload/ts_gridView_M_advancedExcelUpload_2/ts_gridView_M_advancedExcelUpload_2_upload.xlsx (데이터 3행 xlsA1 ~ xlsC4)\n[절차]\n1. par 옵션(useModalDisable / features / frameModal / wframe) 값을 선택한다\n2. advancedExcelUpload 버튼을 클릭한다\n3. 열린 업로드 창에서 Excel 파일을 선택하고 File Upload 를 실행한다\n4. 업로드결과확인 버튼을 클릭한다\n[확인]\n- 2번 직후 결과창에 팝업창 종류 / 팝업창 위치와 크기 / 부모창 비활성화 / Frame 비활성화 상태가 출력됨\n- 부모창 비활성화는 부모 화면의 버튼과 옵션이 클릭 가능한지로도 확인\n- Frame 비활성화는 대상 Frame 영역 위를 덮는 레이어와 출력된 대상 Frame ID 로 확인\n- wframe 은 useModalDisable / features 의 전제 조건 설정용이며 본 샘플의 검증 대상이 아님"', '', 'label1', wf_body_sample.getObj("grp_label"));
}



// 테스트 샘플 Frame 안에 선언된 GridView 를 반환한다.
scwin.getTarget = function () {
    return wf_body_sample.getObj("target1");
}



// par 옵션값으로 advancedExcelUpload options 객체를 구성한다.
//  · 선택(필수여부 N) 파라미터는 미설정(빈값) 이면 객체에 담지 않아 생략되도록 한다.
//  · useModalDisable 은 String 형과 Boolean 형의 동작을 확인해야 하므로 BOOL_TRUE / BOOL_FALSE 선택 시 Boolean true / false 를 전달한다.
//  · frameModal 은 Boolean 형과 String 형의 적용 차이를 확인해야 하므로 BOOL_TRUE 선택 시 Boolean true 를 전달한다.
//  · wframe 은 Boolean 타입이므로 gdl_boolean 라벨(getText)을 Boolean 으로 변환하여 전달한다.
scwin.buildOptions = function () {
    let options = {};

    let vModal = par_useModalDisable.getValue();
    if (vModal === "BOOL_TRUE") {
        options.useModalDisable = true;
    } else if (vModal === "BOOL_FALSE") {
        options.useModalDisable = false;
    } else if (vModal !== "") {
        options.useModalDisable = vModal;
    }

    let vFeatures = par_features.getValue();
    if (vFeatures !== "") {
        options.features = vFeatures;
    }

    let vFrameModal = par_frameModal.getValue();
    if (vFrameModal === "BOOL_TRUE") {
        options.frameModal = true;
    } else if (vFrameModal !== "") {
        options.frameModal = vFrameModal;
    }

    let vWframe = par_wframe.getText();
    if (vWframe === "true") {
        options.wframe = true;
    } else if (vWframe === "false") {
        options.wframe = false;
    }

    return options;
}



// advancedExcelUpload 실행
//  · 설정한 옵션값을 그대로 되출력하지 않고, 실제로 열린 Excel 파일 선택 팝업창의 렌더 상태를 읽어 출력한다.
scwin.btn_advancedExcelUpload_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    scwin.getTarget().advancedExcelUpload(scwin.buildOptions());

    setTimeout(scwin.printUploadState, 1200);
}



// 실제로 열린 Excel 파일 선택 팝업창의 정보를 반환한다.
//  · wframe 적용 시 화면 내 레이어(부모 문서), 미적용 시 window 이름 fileupWindow 인 별도 팝업창이다.
//  · 별도 팝업창은 로딩이 끝나기 전까지 about:blank 이므로 로딩 중임을 알린다.
scwin.getUploadInfo = function () {
    let objLayer = document.querySelector("div[id$='_excelPop']");
    if (objLayer !== null && document.querySelector("input[name='filename']") !== null) {
        let objRect = objLayer.getBoundingClientRect();
        return {
            "kind" : "화면 내 레이어(wframe)",
            "url" : document.location.href,
            "left" : Math.round(objRect.left),
            "top" : Math.round(objRect.top),
            "width" : Math.round(objRect.width),
            "height" : Math.round(objRect.height)
        };
    }

    let objWin = window.open("", "fileupWindow");
    if (objWin === null || objWin.closed) return null;
    if (objWin.location.href === "about:blank") return { "loading" : true, "win" : objWin };

    return {
        "kind" : "별도 팝업창",
        "url" : objWin.location.href,
        "left" : objWin.screenX,
        "top" : objWin.screenY,
        "width" : objWin.outerWidth,
        "height" : objWin.outerHeight
    };
}



// 실제로 열린 Excel 파일 선택 팝업창의 형태 / 위치 / 크기와 부모창 및 Frame 비활성화(모달) 상태를 출력한다.
//  · 부모창 비활성화는 부모 문서를 덮는 모달 레이어(div.w2modal / div.w2modal_popup)의 표시 개수와
//    부모창 컴포넌트(btn_getResult)의 disabled 상태로 확인한다.
//  · Frame 비활성화는 대상 Frame 에 렌더된 모달 레이어(div.w2_wframe_modal)의 표시 개수와 대상 Frame ID 로 확인한다.
scwin.printUploadState = function (nRetry) {
    let bottom = wf_body_bottom.getObj("scwin");
    nRetry = nRetry || 0;

    let objInfo = scwin.getUploadInfo();

    if (objInfo !== null && objInfo.loading === true) {
        if (nRetry < 6) {
            setTimeout(function () { scwin.printUploadState(nRetry + 1); }, 500);
            return;
        }
        objInfo.win.close();
        objInfo = null;
    }

    if (objInfo === null) {
        bottom.setReturnValue("팝업창 종류 : 열려있지 않음");
        bottom.setReturnValue("팝업창 위치 및 크기 : 없음");
    } else {
        bottom.setReturnValue("팝업창 종류 : " + objInfo.kind + " / 실제 열린 경로 : " + objInfo.url);
        bottom.setReturnValue("팝업창 위치 및 크기 : left=" + objInfo.left + ", top=" + objInfo.top + ", width=" + objInfo.width + ", height=" + objInfo.height);
    }

    bottom.setReturnValue("부모창 비활성화 : 모달 레이어 " + scwin.getLayerState("div.w2modal, div.w2modal_popup") + " / 부모창 컴포넌트 disabled = " + btn_getResult.getDisabled());

    let objFrame = document.querySelector("div.w2_wframe_modal");
    let objWframe = (objFrame === null) ? null : objFrame.closest("div.w2wframe");
    bottom.setReturnValue("Frame 비활성화 : 모달 레이어 " + scwin.getLayerState("div.w2_wframe_modal") + " / 대상 Frame : " + (objWframe === null ? "없음" : objWframe.id));
}



// 지정한 셀렉터에 해당하는 레이어의 전체 개수와 실제 표시 개수를 문자열로 반환한다.
scwin.getLayerState = function (strSelector) {
    let objList = document.querySelectorAll(strSelector);
    let nVisible = 0;
    for (let i = 0; i < objList.length; i++) {
        let objStyle = getComputedStyle(objList[i]);
        if (objStyle.display !== "none" && objStyle.visibility !== "hidden") nVisible++;
    }
    return "전체 " + objList.length + "개 / 표시 " + nVisible + "개";
}



// 업로드 결과 확인 : GridView 에 반영된 데이터를 출력한다.
scwin.btn_getResult_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.setReturnValue("=====btn_getResult_onclick=====");

    let objTarget = scwin.getTarget();
    let cnt = objTarget.getRowCount();
    bottom.setReturnValue("Row 수 : " + cnt);
    for (let i = 0; i < cnt; i++) {
        bottom.setReturnValue("[" + i + "] " + objTarget.getCellData(i, "col1") + " | " + objTarget.getCellData(i, "col2") + " | " + objTarget.getCellData(i, "col3") + " | " + objTarget.getCellData(i, "col4"));
    }
}
